'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/transactions — direct Mobile Money collect, and transaction lookups.
 */
class Transactions {
  constructor(client) {
    this.client = client;
  }

  /**
   * List transactions.
   * @param {object} [params] Query params (e.g. page, limit, status, type)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/transactions', params));
  }

  /**
   * Retrieve a transaction by reference.
   * @param {string} reference
   */
  retrieve(reference) {
    return this.client.request('GET', `/v1/transactions/${encodeURIComponent(reference)}`);
  }

  /**
   * Get just the status of a transaction (lightweight polling call).
   * @param {string} reference
   */
  status(reference) {
    return this.client.request('GET', `/v1/transactions/${encodeURIComponent(reference)}/status`);
  }

  /**
   * Directly collect a Mobile Money payment (no order/cart involved).
   * @param {object} params
   * @param {number} params.amount          100–2,000,000
   * @param {string} params.currency        e.g. "XOF"
   * @param {string} params.operator_code   e.g. "ORANGE_MONEY_CI", "MTN_MONEY_CI", "FLOOZ_MONEY_CI", "WAVE_MONEY_CI"
   * @param {string} params.external_ref    Your own idempotent reference
   * @param {string} [params.otp]           Required for Orange Money
   * @param {string} [params.payer_phone]
   * @param {string} [params.payer_phone_prefix]
   * @param {string} [params.payer_first_name]
   * @param {string} [params.payer_last_name]
   * @param {string} [params.payer_email]
   * @param {string} [params.customer_id]
   * @param {string} [params.order_id]
   * @param {string} [params.success_url]
   * @param {string} [params.error_url]
   * @param {string} [params.note]
   */
  collect(params) {
    return this.client.request('POST', '/v1/transactions/collect', params);
  }
}

module.exports = Transactions;
